  `changed_by` bigint DEFAULT NULL,
  `notes` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(6) DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `order_status_history_order_status_history_changed_by_fkey` (`changed_by`),
  KEY `order_status_history_order_status_history_order_id_fkey` (`order_id`),
