--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT (uuid()),
  `buyer_id` bigint NOT NULL,
  `subtotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `discount_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shipping_fee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `payment_method` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_at` datetime(6) DEFAULT CURRENT_TIMESTAMP(6),
  `order_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seller_id` bigint DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'to_ship',
  `items` json DEFAULT NULL,
  `shipping_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shipping_address` json DEFAULT NULL,
  `payment_method_id` bigint DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `cancellation_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancellation_note` longtext COLLATE utf8mb4_unicode_ci,
  `buyer_note` longtext COLLATE utf8mb4_unicode_ci,
  `voucher_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_buyer_id` bigint DEFAULT NULL,
  `app_seller_id` bigint DEFAULT NULL,
  `coins_used` bigint NOT NULL DEFAULT '0',
  `coin_discount_amount` decimal(65,20) NOT NULL DEFAULT '0.00000000000000000000',
  `platform_voucher_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `platform_discount_amount` decimal(65,20) NOT NULL DEFAULT '0.00000000000000000000',
  `gcash_purchase_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `commerce_snapshot` json DEFAULT NULL,
  `buyer_confirmed_at` timestamp NULL DEFAULT NULL,
  `delivery_guaranteed_from` datetime DEFAULT NULL,
  `delivery_guaranteed_by` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orders_gcash_purchase_id_unique` (`gcash_purchase_id`),
  KEY `orders_orders_app_buyer_id_fkey` (`app_buyer_id`),
  KEY `orders_orders_app_seller_id_fkey` (`app_seller_id`),
  KEY `orders_orders_buyer_id_foreign` (`buyer_id`),
  KEY `orders_orders_platform_voucher_id_fkey` (`platform_voucher_id`),
  KEY `orders_status_index` (`status`),
  KEY `orders_delivery_guaranteed_from_index` (`delivery_guaranteed_from`),
  KEY `orders_delivery_guaranteed_by_index` (`delivery_guaranteed_by`),
  CONSTRAINT `orders_gcash_purchase_id_foreign` FOREIGN KEY (`gcash_purchase_id`) REFERENCES `gcash_purchases` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `orders_orders_app_buyer_id_fkey` FOREIGN KEY (`app_buyer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `orders_orders_app_seller_id_fkey` FOREIGN KEY (`app_seller_id`) REFERENCES `users` (`id`),
  CONSTRAINT `orders_orders_buyer_id_foreign` FOREIGN KEY (`buyer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `orders_orders_platform_voucher_id_fkey` FOREIGN KEY (`platform_voucher_id`) REFERENCES `platform_vouchers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `orders`
--

LOCK TABLES `orders` WRITE;
/*!40000 ALTER TABLE `orders` DISABLE KEYS */;
