--
-- Table structure for table `settings`
--

DROP TABLE IF EXISTS `settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `settings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `platform_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PocketFinds',
  `support_email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'anchetanicole1020@gmail.com',
  `commission_rate` decimal(5,2) NOT NULL DEFAULT '10.00',
  `google_signin_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `new_registrations_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `maintenance_mode` tinyint(1) NOT NULL DEFAULT '0',
  `email_notifications_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `hero_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hero_tagline` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'Find It. Love It. Pocket It.',
  `hero_subtitle` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT 'Browse products from verified local sellers â€” pet supplies, electronics, fashion, home essentials, and more.',
  `hero_cta_text` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT 'Browse Products',
  `hero_overlay` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'dark',
  `hero_image_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hero_crop_x` tinyint unsigned NOT NULL DEFAULT '50',
  `hero_crop_y` tinyint unsigned NOT NULL DEFAULT '50',
  `hero_crop_zoom` tinyint unsigned NOT NULL DEFAULT '100',
  `hero_2_crop_x` tinyint unsigned NOT NULL DEFAULT '50',
  `hero_2_crop_y` tinyint unsigned NOT NULL DEFAULT '50',
  `hero_2_crop_zoom` tinyint unsigned NOT NULL DEFAULT '100',
  `auth_collage_image_data` mediumblob,
  `auth_collage_image_mime` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `auth_collage_image_sha256` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
