--
-- Table structure for table `shipment_hub_legs`
--

DROP TABLE IF EXISTS `shipment_hub_legs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shipment_hub_legs` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT (uuid()),
  `shipment_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sequence` int NOT NULL,
  `leg_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_hub` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `to_hub` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rider_id` bigint DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `requested_at` datetime DEFAULT NULL,
  `requested_by` bigint DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `approved_by` bigint DEFAULT NULL,
  `rider_confirmed_pickup_at` datetime DEFAULT NULL,
  `from_province` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_province` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transfer_batch_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shipment_hub_legs_shipment_id_sequence_unique` (`shipment_id`,`sequence`),
  KEY `shipment_hub_legs_shipment_hub_legs_approved_by_foreign` (`approved_by`),
  KEY `shipment_hub_legs_shipment_hub_legs_requested_by_foreign` (`requested_by`),
  KEY `shipment_hub_legs_shipment_hub_legs_rider_id_foreign` (`rider_id`),
  KEY `shipment_hub_legs_from_hub_from_province_index` (`from_hub`,`from_province`),
  KEY `shipment_hub_legs_to_hub_to_province_index` (`to_hub`,`to_province`),
  KEY `shipment_hub_legs_transfer_batch_id_index` (`transfer_batch_id`),
  CONSTRAINT `shipment_hub_legs_shipment_hub_legs_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shipment_hub_legs_shipment_hub_legs_requested_by_foreign` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shipment_hub_legs_shipment_hub_legs_rider_id_foreign` FOREIGN KEY (`rider_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shipment_hub_legs_shipment_hub_legs_shipment_id_foreign` FOREIGN KEY (`shipment_id`) REFERENCES `shipments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `shipment_hub_legs_transfer_batch_id_foreign` FOREIGN KEY (`transfer_batch_id`) REFERENCES `hub_transfer_batches` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `shipment_hub_legs`
